#include <stdio.h>
#include <regex.h>

int main() {
    regex_t regex;
    regmatch_t pmatch[1];
    const char *pattern = "[0-9]+";
    const char *str = "abc123xyz";

    regcomp(&regex, pattern, REG_EXTENDED);
    if (regexec(&regex, str, 1, pmatch, 0) == 0) {
        printf("Match: start=%d, end=%d\n", (int)pmatch[0].rm_so, (int)pmatch[0].rm_eo);
        // 输出: Match: start=3, end=6
        // 即 "123" 在 "abc123xyz" 的下标3~6（不含6）
    }
    regfree(&regex);
    return 0;
}

